def enclosed(g, wallfn, diag=False, border_open=False):
    zeros=[(r,c) for r in range(7) for c in range(7) if not wallfn(g[r][c])]
    # flood from border through non-wall
    start=[(r,c) for r,c in zeros if r in(0,6) or c in(0,6)] if not border_open else []
    if border_open:
        # treat outside as passable: enclosed = zeros with no path to edge; simulate by border_open meaning edge is wall
        start=[]
    seen=set(start); q=deque(start)
    while q:
        r,c=q.popleft()
        for nr,nc in neigh(r,c,diag):
            if 0<=nr<7 and 0<=nc<7 and (nr,nc) not in seen and not wallfn(g[nr][nc]):
                seen.add((nr,nc)); q.append((nr,nc))
    if border_open:
        # enclosed = zeros not connected to edge; approximate: connected-to-border zeros are 'seen' plus border zeros themselves are open
        pass
    return set(zeros)-seen

